cat > server/services/issue-dependency-service.ts <<'E'
/**
 * Issue dependencies ("blocked by" links): authorization, cycle detection, the completion gate helpers and the unblocked-notification reaction.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, assertNotArchived, subscribe, notify
 */
import { subscribe } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived, isArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as dependencyRepo from "@/server/repositories/issue-dependency-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { issueResource, requireFound } from "./_support";
import { notify } from "./notification-service";
import type { IssueId, OrgId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Issue, IssueDependency } from "@/types/issue";
import type { Actor } from "@/types/member";

export class IssueBlockedError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly issueId: IssueId,
    readonly blockerIds: readonly IssueId[],
  ) {
    super(`Issue ${issueId} is blocked by open issues: ${blockerIds.join(", ")}`);
    this.name = "IssueBlockedError";
  }
}

type LinkInput = { orgId: OrgId; issueId: IssueId; blockerId: IssueId };

function isOpen(issue: Issue): boolean {
  return !isArchived(issue) && !CLOSED_ISSUE_STATUSES.includes(issue.status);
}

/** Blockers of `issueId` that are neither archived nor done/canceled. */
export async function listOpenBlockerIds(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly IssueId[]> {
  const blockers = await dependencyRepo.listBlockerIssues(orgId, issueId);
  return blockers.filter(isOpen).map((blocker) => blocker.id);
}

/** Throws `IssueBlockedError` when `issueId` still has an open blocker. */
export async function assertNotBlocked(
  orgId: OrgId,
  issueId: IssueId,
): Promise<void> {
  const open = await listOpenBlockerIds(orgId, issueId);
  if (open.length > 0) throw new IssueBlockedError(issueId, open);
}

export async function addBlocker(
  actor: Actor,
  input: LinkInput,
): Promise<IssueDependency> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  const blocker = requireFound(
    await issueRepo.findIssueById(input.orgId, input.blockerId),
    "Issue",
    input.blockerId,
  );
  assertCan(actor, "issue:update", issueResource(issue));

  if (issue.id === blocker.id) {
    throw new Error("An issue cannot block itself");
  }
  assertNotArchived("Issue", issue.id, issue);
  assertNotArchived("Issue", blocker.id, blocker);

  const existing = await dependencyRepo.findDependency(
    input.orgId,
    input.issueId,
    input.blockerId,
  );
  if (existing) return existing;

  // The link would close a cycle if `issueId` is already reachable from the
  // blocker by following "is blocked by" links.
  const all = await dependencyRepo.listDependencies(input.orgId);
  const blockersOf = new Map<string, string[]>();
  for (const dep of all) {
    const list = blockersOf.get(dep.issueId) ?? [];
    list.push(dep.blockerId);
    blockersOf.set(dep.issueId, list);
  }
  const seen = new Set<string>([input.blockerId]);
  const queue: string[] = [input.blockerId];
  while (queue.length > 0) {
    const current = queue.pop() as string;
    if (current === input.issueId) {
      throw new Error("Adding this blocker would create a dependency cycle");
    }
    for (const next of blockersOf.get(current) ?? []) {
      if (!seen.has(next)) {
        seen.add(next);
        queue.push(next);
      }
    }
  }

  return dependencyRepo.insertDependency(
    input.orgId,
    input.issueId,
    input.blockerId,
    actor.userId,
  );
}

export async function removeBlocker(
  actor: Actor,
  input: LinkInput,
): Promise<boolean> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));

  return dependencyRepo.deleteDependency(
    input.orgId,
    input.issueId,
    input.blockerId,
  );
}

export async function listBlockers(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  const blockers = (await dependencyRepo.listBlockerIssues(orgId, issueId))
    .filter((blocker) => !isArchived(blocker))
    .sort((a, b) => a.number - b.number);

  // Re-read through the issue repository so label ids are populated.
  const full: Issue[] = [];
  for (const blocker of blockers) {
    full.push((await issueRepo.findIssueById(orgId, blocker.id)) ?? blocker);
  }
  return full;
}

/**
 * Called once `blocker` has just gone from open to closed: notifies the
 * assignee of every issue that is now free of open blockers.
 */
async function notifyUnblocked(
  orgId: OrgId,
  blockerId: IssueId,
  actorId: Issue["assigneeId"],
): Promise<void> {
  const blocked = await dependencyRepo.listBlockedIssues(orgId, blockerId);
  for (const issue of blocked) {
    if (!isOpen(issue) || issue.assigneeId === null) continue;
    if ((await listOpenBlockerIds(orgId, issue.id)).length > 0) continue;

    await notify(orgId, "issue_unblocked", [issue.assigneeId], {
      title: "An issue was unblocked",
      body: `Issue ${issue.id} has no open blockers left`,
      href: `/issues/${issue.id}`,
      actorId,
    });
  }
}

export function registerDependencyListeners(): Unsubscribe {
  const offs = [
    subscribe("issue.status_changed", async (payload) => {
      const wasOpen = !CLOSED_ISSUE_STATUSES.includes(payload.from);
      const nowClosed = CLOSED_ISSUE_STATUSES.includes(payload.to);
      if (!wasOpen || !nowClosed) return;
      await notifyUnblocked(payload.orgId, payload.issueId, payload.actorId);
    }),
    subscribe("issue.archived", async (payload) => {
      // Archiving leaves the status untouched, so it is the pre-archive status.
      const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
      if (!issue || CLOSED_ISSUE_STATUSES.includes(issue.status)) return;
      await notifyUnblocked(payload.orgId, payload.issueId, payload.actorId);
    }),
  ];
  return () => {
    for (const off of offs) off();
  };
}
