    input.issueId,
    input.blockerId,
  );
}

export async function listBlockers(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  const blockers = (await dependencyRepo.listBlockerIssues(orgId, issueId))
    .filter((blocker) => !isArchived(blocker))
    .sort((a, b) => a.number - b.number);

  // Re-read through the issue repository so label ids are populated.
  const full: Issue[] = [];
  for (const blocker of blockers) {
    full.push((await issueRepo.findIssueById(orgId, blocker.id)) ?? blocker);
  }
  return full;
}

/**
 * Called once `blocker` has just gone from open to closed: notifies the
 * assignee of every issue that is now free of open blockers.
 */
async function notifyUnblocked(
  orgId: OrgId,
  blockerId: IssueId,
  actorId: Issue["assigneeId"],
): Promise<void> {
  const blocked = await dependencyRepo.listBlockedIssues(orgId, blockerId);
  for (const issue of blocked) {
    if (!isOpen(issue) || issue.assigneeId === null) continue;
    if ((await listOpenBlockerIds(orgId, issue.id)).length > 0) continue;

    await notify(orgId, "issue_unblocked", [issue.assigneeId], {
      title: "An issue was unblocked",
      body: `Issue ${issue.id} has no open blockers left`,
      href: `/issues/${issue.id}`,
      actorId,
    });
  }
}

export function registerDependencyListeners(): Unsubscribe {
  const offs = [
    subscribe("issue.status_changed", async (payload) => {
      const wasOpen = !CLOSED_ISSUE_STATUSES.includes(payload.from);
      const nowClosed = CLOSED_ISSUE_STATUSES.includes(payload.to);
      if (!wasOpen || !nowClosed) return;
      await notifyUnblocked(payload.orgId, payload.issueId, payload.actorId);
    }),
    subscribe("issue.archived", async (payload) => {
      // Archiving leaves the status untouched, so it is the pre-archive status.
      const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
      if (!issue || CLOSED_ISSUE_STATUSES.includes(issue.status)) return;
      await notifyUnblocked(payload.orgId, payload.issueId, payload.actorId);
    }),
  ];
  return () => {
    for (const off of offs) off();
  };
}
